import{_ as a,o,c as e,a3 as d}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"로컬 도구 개요","description":"Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui 비교; MiniTavern용 로컬 OpenAI 호환 도구 선택.","frontmatter":{"title":"로컬 도구 개요","description":"Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui 비교; MiniTavern용 로컬 OpenAI 호환 도구 선택.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"로컬 도구 개요 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui 비교; MiniTavern용 로컬 OpenAI 호환 도구 선택."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/local/tools"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/local/tools"}]]},"headers":[],"relativePath":"ko/local/tools.md","filePath":"ko/local/tools.md","lastUpdated":1787224147000}'),l={name:"ko/local/tools.md"};function r(i,t,n,s,c,p){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="도구-개요" tabindex="-1">도구 개요 <a class="header-anchor" href="#도구-개요" aria-label="Permalink to &quot;도구 개요&quot;">​</a></h1><p>MiniTavern은 상대가 <strong>OpenAI 호환</strong> Chat Completions（또는 매핑 가능）을 제공하면 「Custom」모델 연결로 붙일 수 있습니다. 아래 표로 도구를 고르세요.</p><h2 id="비교" tabindex="-1">비교 <a class="header-anchor" href="#비교" aria-label="Permalink to &quot;비교&quot;">​</a></h2><table tabindex="0"><thead><tr><th>도구</th><th>난이도</th><th>UI</th><th>모델 받기</th><th>롤플레이</th><th>전형 Base URL</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/ollama/install">Ollama</a></td><td>★☆☆</td><td>트레이 + CLI</td><td><code>ollama pull</code></td><td>일반 대화 강함</td><td><code>http://IP:11434/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/lmstudio/install">LM Studio</a></td><td>★☆☆</td><td>풀 GUI</td><td>앱 내 다운로드</td><td>일반</td><td><code>http://IP:1234/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/koboldcpp/install">KoboldCPP</a></td><td>★★☆</td><td>경량 GUI/CLI</td><td>자체 GGUF</td><td><strong>RP 커뮤니티 정석</strong></td><td><code>http://IP:5001/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/llamacpp/install">llama.cpp server</a></td><td>★★★</td><td>CLI</td><td>자체 GGUF</td><td>통제·경량</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/localai/install">LocalAI</a></td><td>★★☆</td><td>API / 선택 UI</td><td>YAML / 이미지</td><td>다중 백엔드</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/jan/install">Jan</a></td><td>★☆☆</td><td>데스크톱 App</td><td>앱 내</td><td>일반</td><td>앱 「API」페이지</td></tr><tr><td><a href="/ultra_guides/ko/textgen/install">text-generation-webui</a></td><td>★★★</td><td>Web UI</td><td>확장 많음</td><td>플러그인 생태계</td><td>OpenAI 확장 켠 뒤</td></tr></tbody></table><h2 id="한-줄로-고르기" tabindex="-1">한 줄로 고르기 <a class="header-anchor" href="#한-줄로-고르기" aria-label="Permalink to &quot;한 줄로 고르기&quot;">​</a></h2><ol><li><strong>가장 빨리</strong>: Ollama 또는 LM Studio → <a href="/ultra_guides/ko/quickstart">30분 퀵스타트</a></li><li><strong>롤플레이 프리셋 / 샘플러</strong>: KoboldCPP</li><li><strong>GGUF 있음, 의존 최소</strong>: llama.cpp <code>llama-server</code></li><li><strong>Docker / 통합 호환 층</strong>: LocalAI</li><li><strong>올인원 데스크톱</strong>: Jan</li><li><strong>이미 oobabooga</strong>: OpenAI 호환 확장 후 MiniTavern</li></ol><h2 id="공통-요구" tabindex="-1">공통 요구 <a class="header-anchor" href="#공통-요구" aria-label="Permalink to &quot;공통 요구&quot;">​</a></h2><p>어느 도구든:</p><ol><li>서비스가 <strong>LAN</strong> 리슨（<code>0.0.0.0</code> 또는 「LAN 기기 허용」）, <code>127.0.0.1</code>만 바인딩 금지</li><li>방화벽 해당 포트 개방</li><li>폰에 <strong>PC LAN IP</strong>, Base URL에 <code>/v1</code>（도구 문서가 다르면 제외）</li><li>모델명이 도구에 표시된 <strong>id / 이름과 완전 일치</strong></li></ol><p>다음: <a href="./models">추천 모델</a> · <a href="/ultra_guides/ko/connect-app/minitavern">MiniTavern 설정</a></p>',10)])])}const g=a(l,[["render",r]]);export{u as __pageData,g as default};
